insert into public.panfletos
  (id, titulo, categoria, descricao, descricao_longa, palavras_chave, pdf_url, imagem_url, paginas, data_publicacao, publicado)
values
  ('acidente-ofidico-o-que-fazer-apos-uma-picada', 'Acidente ofídico: o que fazer após uma picada', 'Clínica Médica', 'Picada de serpente pode causar dor, inchaço, sangramento, alterações neurológicas ou musculares. O soro correto depende do tipo de acidente e deve ser administrado em serviço de saúde.', '[{"titulo":"Sobre o tema","texto":"Picada de serpente pode causar dor, inchaço, sangramento, alterações neurológicas ou musculares. O soro correto depende do tipo de acidente e deve ser administrado em serviço de saúde.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Lave o local com água e sabão, mantenha a pessoa em repouso e procure atendimento imediatamente.","Retire anéis, pulseiras ou objetos apertados do membro.","Se for seguro, fotografe o animal sem tentar capturá-lo."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Não faça torniquete, cortes, sucção nem aplique substâncias caseiras.","Inchaço progressivo, sangramento, vômitos, visão dupla, fraqueza ou urina escura indicam gravidade."]}]', '{"acidente ofídico","serpente","soro antiofídico","primeiros socorros"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-ofidico-o-que-fazer-apos-uma-picada.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-ofidico-o-que-fazer-apos-uma-picada.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-ofidico-o-que-fazer-apos-uma-picada.png"]', '2026-10-26T20:00:00-03:00', true),
  ('diabetes-mellitus-conhecer-para-cuidar', 'Diabetes mellitus: conhecer para cuidar', 'Clínica Médica', 'Diabetes ocorre quando a glicose permanece elevada no sangue por falta de insulina ou dificuldade de seu uso. Sede excessiva, muita urina, perda de peso e visão embaçada podem aparecer, mas a doença também pode ser silenciosa.', '[{"titulo":"Sobre o tema","texto":"Diabetes ocorre quando a glicose permanece elevada no sangue por falta de insulina ou dificuldade de seu uso. Sede excessiva, muita urina, perda de peso e visão embaçada podem aparecer, mas a doença também pode ser silenciosa.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Faça acompanhamento e exames conforme orientação da equipe de saúde.","Use corretamente os medicamentos e observe os pés todos os dias.","Alimentação, movimento e controle da pressão ajudam a reduzir complicações."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Confusão, sonolência, vômitos repetidos, respiração alterada ou desidratação exigem urgência.","Ferida no pé, glicose muito baixa com alteração de consciência ou sintomas persistentes precisam de atendimento."]}]', '{"diabetes","glicose","insulina","pé diabético","prevenção"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/diabetes-mellitus-conhecer-para-cuidar.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/diabetes-mellitus-conhecer-para-cuidar.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/diabetes-mellitus-conhecer-para-cuidar.png"]', '2026-10-28T10:00:00-03:00', true),
  ('acidente-com-arraia-primeiros-cuidados', 'Acidente com arraia: primeiros cuidados', 'Clínica Médica', 'O ferrão da arraia causa ferida dolorosa, pode deixar fragmentos e aumentar o risco de infecção. A dor costuma ser intensa e o ferimento precisa ser avaliado.', '[{"titulo":"Sobre o tema","texto":"O ferrão da arraia causa ferida dolorosa, pode deixar fragmentos e aumentar o risco de infecção. A dor costuma ser intensa e o ferimento precisa ser avaliado.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Saia da água com segurança, lave o local e procure atendimento.","Água morna suportável pode ajudar na dor enquanto se busca cuidado.","Mantenha a vacinação contra tétano atualizada."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Não corte, não sugue e não tente retirar fragmentos profundos.","Sangramento intenso, desmaio, falta de ar, ferida no tórax/abdome ou dor persistente exigem emergência."]}]', '{"acidente com arraia","ferimento","primeiros socorros","tétano"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-com-arraia-primeiros-cuidados.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-com-arraia-primeiros-cuidados.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/acidente-com-arraia-primeiros-cuidados.png"]', '2026-10-30T10:00:00-03:00', true),
  ('infeccao-do-trato-urinario-sintomas-e-cuidados', 'Infecção do trato urinário: sintomas e cuidados', 'Clínica Médica', 'Infecção urinária pode causar ardor, urgência, aumento da frequência e dor na parte baixa do abdome. Febre e dor nas costas podem indicar acometimento dos rins.', '[{"titulo":"Sobre o tema","texto":"Infecção urinária pode causar ardor, urgência, aumento da frequência e dor na parte baixa do abdome. Febre e dor nas costas podem indicar acometimento dos rins.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Procure avaliação para confirmar a causa e definir se precisa de antibiótico.","Beba líquidos conforme sua condição de saúde.","Não use antibiótico guardado nem interrompa o tratamento prescrito."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Febre, calafrios, vômitos, dor lombar, confusão, gravidez ou piora rápida exigem avaliação precoce.","Pouca urina ou mal-estar intenso precisa de atendimento imediato."]}]', '{"infecção urinária","ITU","ardor ao urinar","antibióticos"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/infeccao-do-trato-urinario-sintomas-e-cuidados.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/infeccao-do-trato-urinario-sintomas-e-cuidados.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/infeccao-do-trato-urinario-sintomas-e-cuidados.png"]', '2026-11-02T10:00:00-03:00', true),
  ('febre-sinais-de-alarme-medicamentos-e-cuidados', 'Febre: sinais de alarme, medicamentos e cuidados', 'Clínica Médica', 'Febre é um sinal do organismo, não uma doença isolada. O contexto, a duração, a idade e os sintomas associados ajudam a identificar a causa e a gravidade.', '[{"titulo":"Sobre o tema","texto":"Febre é um sinal do organismo, não uma doença isolada. O contexto, a duração, a idade e os sintomas associados ajudam a identificar a causa e a gravidade.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Meça a temperatura, mantenha hidratação e observe a evolução.","Use antitérmicos apenas na dose e no intervalo orientados.","Não alterne remédios nem use antibiótico por conta própria."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Rigidez na nuca, falta de ar, confusão, convulsão, manchas arroxeadas, desidratação ou piora intensa exigem urgência.","Bebês pequenos, gestantes, idosos e imunossuprimidos precisam de avaliação mais precoce."]}]', '{"febre","antitérmicos","sinais de alarme","hidratação"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/febre-sinais-de-alarme-medicamentos-e-cuidados.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/febre-sinais-de-alarme-medicamentos-e-cuidados.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/febre-sinais-de-alarme-medicamentos-e-cuidados.png"]', '2026-11-04T10:00:00-03:00', true),
  ('erisipela-e-celulite-infeccoes-da-pele', 'Erisipela e celulite: infecções da pele', 'Clínica Médica', 'Infecções costumam ser quentes, dolorosas e podem se espalhar. Infecção bacteriana mais superficial da pele.', '[{"titulo":"Sobre o tema","texto":"Infecções costumam ser quentes, dolorosas e podem se espalhar. Infecção bacteriana mais superficial da pele. Placa vermelha, quente, dolorosa e inchada. A borda costuma ser mais nítida e elevada.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Infecção de camadas mais profundas da pele e tecido abaixo dela.","Vermelhidão tende a ter bordas menos definidas.","Causa calor, dor e inchaço.","Pode aumentar rapidamente."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Vermelhidão nova que cresce, dói ou aquece.","Inchaço persistente de uma perna.","Mancha com dormência ou fraqueza.","Ferida, secreção ou mau cheiro."]}]', '{"erisipela,","celulite","outra","marca?"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/erisipela-e-celulite-infeccoes-da-pele.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/erisipela-e-celulite-infeccoes-da-pele.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/erisipela-e-celulite-infeccoes-da-pele.png"]', '2026-11-06T10:00:00-03:00', true),
  ('choque-anafilatico-reconhecer-para-agir-rapido', 'Choque anafilático: reconhecer para agir rápido', 'Clínica Médica', 'Anafilaxia é uma reação alérgica grave e rápida. Pode ocorrer após alimentos, medicamentos, picadas ou outras exposições e comprometer respiração e circulação.', '[{"titulo":"Sobre o tema","texto":"Anafilaxia é uma reação alérgica grave e rápida. Pode ocorrer após alimentos, medicamentos, picadas ou outras exposições e comprometer respiração e circulação.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Afaste o possível gatilho quando for seguro e acione o SAMU 192.","Se a pessoa possui autoinjetor de adrenalina prescrito, use conforme o plano médico.","Mantenha a pessoa deitada, salvo dificuldade respiratória ou vômitos."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Inchaço de língua ou garganta, chiado, falta de ar, desmaio, pressão baixa ou urticária generalizada com outros sintomas são emergência.","Não espere a reação passar sozinha."]}]', '{"anafilaxia","alergia grave","adrenalina","emergência"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/choque-anafilatico-reconhecer-para-agir-rapido.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/choque-anafilatico-reconhecer-para-agir-rapido.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/choque-anafilatico-reconhecer-para-agir-rapido.png"]', '2026-11-09T10:00:00-03:00', true),
  ('sepse-sinais-de-alerta-e-atendimento-urgente', 'Sepse: sinais de alerta e atendimento urgente', 'Clínica Médica', 'Sepse acontece quando a resposta do organismo a uma infecção começa a comprometer órgãos. Pode surgir a partir de infecções pulmonares, urinárias, abdominais, de pele e de outros locais.', '[{"titulo":"Sobre o tema","texto":"Sepse acontece quando a resposta do organismo a uma infecção começa a comprometer órgãos. Pode surgir a partir de infecções pulmonares, urinárias, abdominais, de pele e de outros locais.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Procure avaliação se uma infecção vier acompanhada de piora geral importante.","Informe doenças, medicamentos, cirurgias recentes e quando os sintomas começaram.","Não adie atendimento esperando apenas a febre baixar."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Confusão, respiração rápida ou difícil, pressão baixa, pele fria/manchada, pouca urina ou sonolência intensa exigem emergência.","Idosos e imunossuprimidos podem ter sepse mesmo sem febre alta."]}]', '{"sepse","infecção","sinais de alerta","emergência"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/sepse-sinais-de-alerta-e-atendimento-urgente.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/sepse-sinais-de-alerta-e-atendimento-urgente.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/sepse-sinais-de-alerta-e-atendimento-urgente.png"]', '2026-11-11T10:00:00-03:00', true),
  ('falta-de-ar-causas-e-quando-procurar-ajuda', 'Falta de ar: causas e quando procurar ajuda', 'Pneumologia', 'Falta de ar pode vir dos pulmões, do coração, do sangue, de infecções ou de outras condições. O início, os gatilhos e os sintomas associados orientam a investigação.', '[{"titulo":"Sobre o tema","texto":"Falta de ar pode vir dos pulmões, do coração, do sangue, de infecções ou de outras condições. O início, os gatilhos e os sintomas associados orientam a investigação.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Interrompa o esforço e fique em posição confortável.","Use somente medicamentos já prescritos para essa situação.","Observe início, duração, chiado, febre, dor e inchaço."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar súbita ou em repouso, lábios arroxeados, dor no peito, desmaio, confusão ou incapacidade de falar frases exige emergência.","Acione o SAMU 192 se houver piora rápida."]}]', '{"falta de ar","dispneia","sinais de gravidade","emergência"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/falta-de-ar-causas-e-quando-procurar-ajuda.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/falta-de-ar-causas-e-quando-procurar-ajuda.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/falta-de-ar-causas-e-quando-procurar-ajuda.png"]', '2026-11-13T10:00:00-03:00', true),
  ('asma-controle-crises-e-sinais-de-alerta', 'Asma: controle, crises e sinais de alerta', 'Pneumologia', 'Asma é uma inflamação crônica das vias aéreas que causa chiado, aperto no peito, tosse e falta de ar. Os sintomas variam e podem piorar à noite, com exercício, infecções ou exposição a gatilhos.', '[{"titulo":"Sobre o tema","texto":"Asma é uma inflamação crônica das vias aéreas que causa chiado, aperto no peito, tosse e falta de ar. Os sintomas variam e podem piorar à noite, com exercício, infecções ou exposição a gatilhos.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Use o controlador e o alívio conforme o plano prescrito.","Confira a técnica do inalador e reconheça seus gatilhos.","Mantenha acompanhamento mesmo quando estiver sem sintomas."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Dificuldade para falar, lábios arroxeados, sonolência, esforço intenso para respirar ou pouca resposta ao remédio de alívio exigem emergência.","Crises repetidas indicam controle inadequado e precisam de revisão."]}]', '{"asma","chiado","bombinha","crise de asma"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/asma-controle-crises-e-sinais-de-alerta.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/asma-controle-crises-e-sinais-de-alerta.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/asma-controle-crises-e-sinais-de-alerta.png"]', '2026-11-16T10:00:00-03:00', true),
  ('espirometria-o-exame-do-sopro', 'Espirometria: o exame do sopro', 'Pneumologia', 'A espirometria mede quanto ar a pessoa consegue inspirar e expirar e com que velocidade. Ajuda no diagnóstico e acompanhamento de asma, DPOC e outras alterações respiratórias.', '[{"titulo":"Sobre o tema","texto":"A espirometria mede quanto ar a pessoa consegue inspirar e expirar e com que velocidade. Ajuda no diagnóstico e acompanhamento de asma, DPOC e outras alterações respiratórias.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Use roupa confortável e siga as orientações sobre inaladores e alimentação.","Avise sobre infecção recente, cirurgia, gravidez ou problemas cardíacos.","Durante o exame, será necessário soprar com força várias vezes para obter medidas confiáveis."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["O exame deve ser adiado ou ajustado quando houver condição clínica que aumente o risco, conforme avaliação da equipe.","Dor no peito, tontura intensa ou falta de ar importante durante o teste deve ser comunicada imediatamente."]}]', '{"espirometria","exame do sopro","asma","DPOC"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/espirometria-o-exame-do-sopro.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/espirometria-o-exame-do-sopro.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/espirometria-o-exame-do-sopro.png"]', '2026-11-18T10:00:00-03:00', true),
  ('tosse-causas-comuns-e-sinais-de-alerta', 'Tosse: causas comuns e sinais de alerta', 'Pneumologia', 'Tosse é um reflexo de proteção e pode ocorrer em resfriados, alergias, asma, refluxo, uso de medicamentos e outras doenças. A duração e os sintomas associados ajudam na investigação.', '[{"titulo":"Sobre o tema","texto":"Tosse é um reflexo de proteção e pode ocorrer em resfriados, alergias, asma, refluxo, uso de medicamentos e outras doenças. A duração e os sintomas associados ajudam na investigação.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Hidrate-se, evite fumaça e observe se a tosse é seca ou com secreção.","Não use antibióticos ou xaropes por conta própria.","Procure avaliação se durar semanas ou estiver piorando."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Sangue no escarro, falta de ar, dor no peito, febre persistente, perda de peso ou queda do estado geral exigem avaliação rápida.","Engasgo súbito com dificuldade respiratória é emergência."]}]', '{"tosse","sinais de alerta","vias aéreas","pneumologia"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tosse-causas-comuns-e-sinais-de-alerta.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tosse-causas-comuns-e-sinais-de-alerta.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tosse-causas-comuns-e-sinais-de-alerta.png"]', '2026-11-20T10:00:00-03:00', true),
  ('evali-lesao-pulmonar-associada-ao-uso-de-vape', 'EVALI: lesão pulmonar associada ao uso de vape', 'Pneumologia', 'EVALI é uma lesão pulmonar associada ao uso de cigarros eletrônicos ou produtos de vaping. Pode causar tosse, dor no peito, falta de ar, febre e sintomas gastrointestinais.', '[{"titulo":"Sobre o tema","texto":"EVALI é uma lesão pulmonar associada ao uso de cigarros eletrônicos ou produtos de vaping. Pode causar tosse, dor no peito, falta de ar, febre e sintomas gastrointestinais.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Suspenda o uso de vape e procure avaliação.","Informe quais produtos foram usados, há quanto tempo e com que frequência.","Não retome o uso após melhora sem orientação."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar, lábios arroxeados, dor no peito, confusão ou piora rápida exige emergência.","Saturação baixa ou incapacidade de realizar atividades habituais precisa de avaliação imediata."]}]', '{"EVALI","vape","cigarro eletrônico","lesão pulmonar"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/evali-lesao-pulmonar-associada-ao-uso-de-vape.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/evali-lesao-pulmonar-associada-ao-uso-de-vape.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/evali-lesao-pulmonar-associada-ao-uso-de-vape.png"]', '2026-11-23T10:00:00-03:00', true),
  ('broncoscopia-preparo-exame-e-cuidados', 'Broncoscopia: preparo, exame e cuidados', 'Pneumologia', 'Broncoscopia permite visualizar as vias respiratórias com um aparelho fino e flexível, além de coletar amostras quando necessário. É feita com anestesia local e sedação conforme o caso.', '[{"titulo":"Sobre o tema","texto":"Broncoscopia permite visualizar as vias respiratórias com um aparelho fino e flexível, além de coletar amostras quando necessário. É feita com anestesia local e sedação conforme o caso.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Respeite o jejum e informe medicamentos, alergias e uso de anticoagulantes.","Organize acompanhante se houver sedação.","Após o exame, aguarde a liberação para comer e beber."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar crescente, dor no peito, febre persistente ou sangramento em quantidade exige contato imediato com o serviço.","Pequena irritação na garganta pode ocorrer, mas piora progressiva não é esperada."]}]', '{"broncoscopia","vias aéreas","sedação","biópsia"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/broncoscopia-preparo-exame-e-cuidados.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/broncoscopia-preparo-exame-e-cuidados.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/broncoscopia-preparo-exame-e-cuidados.png"]', '2026-11-25T10:00:00-03:00', true),
  ('pneumonia-x-gripe-x-covid-19-entenda-as-diferencas', 'Pneumonia x gripe x COVID-19: entenda as diferenças', 'Pneumologia', 'Gripe e COVID-19 são infecções virais que podem causar febre, tosse e dores; pneumonia é uma infecção do pulmão que pode ser viral ou bacteriana. Os sintomas se sobrepõem e o exame clínico é importante.', '[{"titulo":"Sobre o tema","texto":"Gripe e COVID-19 são infecções virais que podem causar febre, tosse e dores; pneumonia é uma infecção do pulmão que pode ser viral ou bacteriana. Os sintomas se sobrepõem e o exame clínico é importante.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Mantenha hidratação, repouso e evite contato próximo enquanto houver sintomas contagiosos.","Faça testagem e use máscara conforme orientação local.","Não use antibiótico sem avaliação, pois ele não trata vírus."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar, dor no peito, confusão, lábios arroxeados, febre persistente ou queda importante do estado geral exigem atendimento.","Idosos, gestantes, crianças pequenas e pessoas com doenças crônicas precisam de avaliação mais precoce."]}]', '{"pneumonia","gripe","COVID-19","sintomas respiratórios"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/pneumonia-x-gripe-x-covid-19-entenda-as-diferencas.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/pneumonia-x-gripe-x-covid-19-entenda-as-diferencas.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/pneumonia-x-gripe-x-covid-19-entenda-as-diferencas.png"]', '2026-11-27T10:00:00-03:00', true),
  ('hipertensao-arterial-diagnostico-controle-e-cuidados', 'Hipertensão arterial: diagnóstico, controle e cuidados', 'Cardiologia', 'Hipertensão é a elevação persistente da pressão arterial e muitas vezes não causa sintomas. O diagnóstico não depende de uma medida isolada: exige técnica correta, repetição e avaliação profissional, podendo incluir MAPA ou MRPA.', '[{"titulo":"Sobre o tema","texto":"Hipertensão é a elevação persistente da pressão arterial e muitas vezes não causa sintomas. O diagnóstico não depende de uma medida isolada: exige técnica correta, repetição e avaliação profissional, podendo incluir MAPA ou MRPA.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Meça a pressão em repouso, com manguito adequado e braço apoiado.","Use os medicamentos nos horários prescritos e não interrompa por conta própria.","Reduza sal, mantenha atividade física e acompanhe diabetes, colesterol e peso."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Dor no peito, falta de ar intensa, desmaio, fraqueza de um lado do corpo, alteração da fala ou visão exigem emergência.","Valores muito elevados acompanhados de sintomas precisam de avaliação imediata."]}]', '{"hipertensão","pressão alta","diagnóstico","MAPA","MRPA"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/hipertensao-arterial-diagnostico-controle-e-cuidados.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/hipertensao-arterial-diagnostico-controle-e-cuidados.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/hipertensao-arterial-diagnostico-controle-e-cuidados.png"]', '2026-11-30T10:00:00-03:00', true),
  ('cateterismo-cardiaco-como-e-feito', 'Cateterismo cardíaco: como é feito', 'Cardiologia', 'O cateterismo usa um tubo fino introduzido por uma artéria do punho ou da virilha para visualizar vasos do coração e medir pressões. O paciente costuma permanecer acordado, com anestesia local e monitoramento.', '[{"titulo":"Sobre o tema","texto":"O cateterismo usa um tubo fino introduzido por uma artéria do punho ou da virilha para visualizar vasos do coração e medir pressões. O paciente costuma permanecer acordado, com anestesia local e monitoramento.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Informe alergias, gravidez, doença renal e todos os medicamentos, especialmente anticoagulantes.","Siga as orientações de jejum e hidratação da equipe.","Após o exame, mantenha o local protegido e respeite o repouso indicado."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Sangramento que não para, aumento rápido de volume no local, dor no peito, falta de ar ou membro frio/pálido exigem atendimento.","Febre ou piora da dor no ponto de punção também precisa ser comunicada."]}]', '{"cateterismo","coronariografia","contraste","procedimento cardíaco"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/cateterismo-cardiaco-como-e-feito.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/cateterismo-cardiaco-como-e-feito.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/cateterismo-cardiaco-como-e-feito.png"]', '2026-12-02T10:00:00-03:00', true),
  ('arritmias-do-ritmo-ao-cuidado', 'Arritmias: do ritmo ao cuidado', 'Cardiologia', 'Arritmia é uma alteração na frequência ou no ritmo dos batimentos. Pode causar palpitações, sensação de falha, cansaço ou tontura, mas o tipo só pode ser definido com avaliação e registro do ritmo.', '[{"titulo":"Sobre o tema","texto":"Arritmia é uma alteração na frequência ou no ritmo dos batimentos. Pode causar palpitações, sensação de falha, cansaço ou tontura, mas o tipo só pode ser definido com avaliação e registro do ritmo.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Anote quando a palpitação começa, quanto dura e o que estava fazendo.","Evite automedicação e excesso de estimulantes.","Leve a lista de medicamentos e exames anteriores à consulta."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Palpitação com dor no peito, desmaio, falta de ar intensa ou fraqueza súbita exige emergência.","Batimento muito acelerado ou lento com mal-estar importante também deve ser avaliado rapidamente."]}]', '{"arritmia","palpitação","ritmo cardíaco","eletrocardiograma"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/arritmias-do-ritmo-ao-cuidado.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/arritmias-do-ritmo-ao-cuidado.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/arritmias-do-ritmo-ao-cuidado.png"]', '2026-12-04T10:00:00-03:00', true),
  ('insuficiencia-cardiaca-sinais-cuidados-e-acompanhamento', 'Insuficiência cardíaca: sinais, cuidados e acompanhamento', 'Cardiologia', 'Na insuficiência cardíaca, o coração não consegue bombear ou receber sangue adequadamente. Falta de ar, cansaço, inchaço nas pernas e necessidade de dormir mais sentado podem indicar acúmulo de líquido.', '[{"titulo":"Sobre o tema","texto":"Na insuficiência cardíaca, o coração não consegue bombear ou receber sangue adequadamente. Falta de ar, cansaço, inchaço nas pernas e necessidade de dormir mais sentado podem indicar acúmulo de líquido.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Use os medicamentos exatamente como prescritos.","Observe peso, inchaço e piora da falta de ar.","Reduza sal e ajuste líquidos apenas conforme orientação da equipe."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar em repouso, lábios arroxeados, desmaio, dor no peito ou piora rápida do inchaço exigem urgência.","Ganho rápido de peso e redução importante da urina merecem contato precoce com a equipe."]}]', '{"insuficiência cardíaca","falta de ar","edema","coração"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/insuficiencia-cardiaca-sinais-cuidados-e-acompanhamento.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/insuficiencia-cardiaca-sinais-cuidados-e-acompanhamento.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/insuficiencia-cardiaca-sinais-cuidados-e-acompanhamento.png"]', '2026-12-07T10:00:00-03:00', true),
  ('antiacidos-x-ibp-entenda-a-diferenca', 'Antiácidos x IBP: entenda a diferença', 'Gastroenterologia', 'Um neutraliza o ácido; o outro reduz sua produção. Neutralizam temporariamente o ácido já presente no estômago.', '[{"titulo":"Sobre o tema","texto":"Um neutraliza o ácido; o outro reduz sua produção. Neutralizam temporariamente o ácido já presente no estômago. Podem aliviar azia leve por algumas horas. Não tratam a causa e não são indicados para uso diário sem avaliação.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Revise periodicamente se ainda há indicação.","Não suspenda abruptamente tratamento longo sem orientação.","Informe todos os medicamentos e doenças.","Pessoas com doença renal, cardíaca ou dieta com pouco sódio precisam atenção a alguns antiácidos."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Dor no peito com falta de ar, suor frio ou desmaio.","Dificuldade/dor para engolir.","Vômito com sangue ou fezes pretas.","Perda de peso, anemia ou vômitos persistentes."]}]', '{"antiácidos"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/antiacidos-x-ibp-entenda-a-diferenca.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/antiacidos-x-ibp-entenda-a-diferenca.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/antiacidos-x-ibp-entenda-a-diferenca.png"]', '2026-12-09T10:00:00-03:00', true),
  ('tuberculose-transmissao-sintomas-e-tratamento', 'Tuberculose: transmissão, sintomas e tratamento', 'Infectologia', 'Tuberculose é causada por uma bactéria e a forma pulmonar pode ser transmitida pelo ar quando uma pessoa doente, ainda sem tratamento adequado, tosse, fala ou espirra.', '[{"titulo":"Sobre o tema","texto":"Tuberculose é causada por uma bactéria e a forma pulmonar pode ser transmitida pelo ar quando uma pessoa doente, ainda sem tratamento adequado, tosse, fala ou espirra.","itens":[]},{"titulo":"Orientações práticas","texto":"","itens":["Tosse por três semanas ou mais deve ser investigada.","O tratamento é gratuito no SUS e precisa ser completado mesmo após melhora.","Ambientes ventilados e avaliação dos contatos ajudam a interromper a transmissão."]},{"titulo":"Quando ligar o alerta","texto":"","itens":["Falta de ar, sangue ao tossir, fraqueza intensa ou piora importante exige atendimento rápido.","Febre prolongada, suor noturno e emagrecimento também merecem investigação."]}]', '{"tuberculose","tosse","transmissão pelo ar","tratamento"}', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tuberculose-transmissao-sintomas-e-tratamento.png', 'https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tuberculose-transmissao-sintomas-e-tratamento.png', '["https://abrasusprogramadocuidado.github.io/ABRAsus-/assets/panfletos/tuberculose-transmissao-sintomas-e-tratamento.png"]', '2026-12-11T10:00:00-03:00', true)
